package br.com.lealinfo.vidraceiro;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.math.*;
public class CutPackingTest {
 CutPacking.Piece p(String id,String w,String h,int q,String material,boolean rotate){return new CutPacking.Piece(id,id,w,h,q,material,rotate);}
 @Test public void homologatedGeometry(){CutPacking.Result r=CutPacking.calculate("3000","2000",Arrays.asList(p("01","1200","1000",1,"Vidro",true)),true);assertEquals(1,r.sheets.size());assertEquals(0,r.used().compareTo(new BigDecimal("1.2")));assertEquals(0,r.unused().compareTo(new BigDecimal("4.8")));assertEquals(0,r.utilization().compareTo(new BigDecimal("20")));assertEquals(0,r.rejectedQuantity());}
 @Test public void rotationAndRejection(){CutPacking.Piece piece=p("01","2200","1000",1,"",true);assertEquals(1,CutPacking.calculate("2000","3000",Arrays.asList(piece),false).rejectedQuantity());CutPacking.Result r=CutPacking.calculate("2000","3000",Arrays.asList(piece),true);assertTrue(r.sheets.get(0).placed.get(0).rotated);assertEquals(0,r.rejectedQuantity());assertEquals(1,CutPacking.calculate("2000","3000",Arrays.asList(p("01","2200","1000",1,"",false)),true).rejectedQuantity());}
 @Test public void materialAndNoOverlap(){List<CutPacking.Piece> p=Arrays.asList(p("a","1200","1000",6,"A",true),p("b","1000","700",4,"B",true));CutPacking.Result r=CutPacking.calculate("3000","2000",p,true);int count=0;for(CutPacking.Sheet s:r.sheets){for(CutPacking.Placement a:s.placed){count++;assertTrue(a.x.add(a.w).compareTo(r.w)<=0);assertTrue(a.y.add(a.h).compareTo(r.h)<=0);for(CutPacking.Placement b:s.placed)if(a!=b)assertTrue(a.x.add(a.w).compareTo(b.x)<=0||b.x.add(b.w).compareTo(a.x)<=0||a.y.add(a.h).compareTo(b.y)<=0||b.y.add(b.h).compareTo(a.y)<=0);}}assertEquals(10,count);assertTrue(r.sheets.size()>=3);}
}
